68:export async function mergeRun(runId: string, workspaceId: string) {
69:  const db = service();
70:  try { await activeRun(db, runId, workspaceId); } catch (error) { if (error instanceof RunInactive) return false; throw error; }
71:  const { workspace } = await loadWorkspace(db, workspaceId);
72:  const lead = { db, runId, workspace, agent: "lead" as const };
73:  await report(lead, { type: "step", text: "Merging results and resolving conflicts" });
74:  const before = await runProposals(db, runId, workspaceId);
75:  const { proposals, resolutions } = mergeProposals(before);
76:  const kept = new Set(proposals.map(item => item.conflictKey));
77:  const dropped = before.filter(item => !kept.has(item.conflictKey)).map(item => item.conflictKey);
78:  if (dropped.length) checked(await db.from("agent_proposals").delete().eq("run_id", runId).eq("workspace_id", workspaceId).eq("status", "proposed").in("conflict_key", dropped));
79:  for (const item of proposals) {
80:    const original = before.find(other => other.conflictKey === item.conflictKey);
81:    if (original && (original.confidence !== item.confidence || original.notes.length !== item.notes.length))
82:      checked(await db.from("agent_proposals").update({ confidence: item.confidence, notes: item.notes }).eq("run_id", runId).eq("workspace_id", workspaceId).eq("conflict_key", item.conflictKey));
83:  }
84:  for (const text of resolutions.slice(0, 10)) await report(lead, { type: "note", text });
85:  // Repayments of money lent or borrowed wait for review on Home and here; a failed lookup never fails the run.
86:  try { for (const found of await proposeRepayments({ supabase: db, workspace })) await report(lead, { type: "finding", text: found.title }); }
87:  catch (cause) { await report(lead, { type: "note", text: `Could not check loan repayments: ${cause instanceof Error ? cause.message : String(cause)}` }); }
88:  await report(lead, { type: "step", text: `${proposals.length} proposals ready for review` }, { summary: `Merged ${before.length} results into ${proposals.length} proposals; ${resolutions.length} conflicts resolved` });
89:  return true;
90:}
